def _error(r: Response) -> ApiError:
    try:
        code = str(json.loads(r.body)["error"]["code"])
    except (ValueError, KeyError, TypeError):
        code = ""
    return ApiError(r.status, code)


def _wait(transport: Transport, failed: int, r: Response | None) -> None:
    """Waits before the attempt after attempt number `failed`."""
    seconds: float = BACKOFF[failed - 1]
    if r is not None:
        for name, value in r.headers.items():
            if name.lower() == "retry-after":
                try:
                    seconds = int(str(value).strip())
                except ValueError:
                    pass
                break
    transport.sleep(seconds)


def _attempt(transport: Transport, method: str, path: str, headers: dict[str, str], body: dict[str, Any] | None):
    """One request. Returns (response, None) for a final answer or (response-or-None, exception) when retryable."""
    try:
        r = transport.send(method, path, dict(headers), body)
    except ConnectionError as e:
        return None, e
    if r.status in (200, 201):
        return r, None
    err = _error(r)
    if r.status in RETRY_STATUSES or r.status == 429 or (r.status == 409 and err.code == "idempotency_in_progress"):
        return r, err
    raise err


def _call(transport: Transport, method: str, path: str, body: dict[str, Any] | None = None, key: str | None = None) -> Any:
    headers = {"Idempotency-Key": key} if key else {}
    for n in range(1, MAX_ATTEMPTS + 1):
        r, failure = _attempt(transport, method, path, headers, body)
        if failure is None:
            return json.loads(r.body)
        if n == MAX_ATTEMPTS:
            raise failure
        _wait(transport, n, r)
    raise AssertionError("unreachable")


