    return _hold(_call(transport, "POST", f"{BASE}/holds", body))''','''"reference": reference}
    return _hold(_call(transport, "POST", f"{BASE}/holds", body, _key("hold", reference)))''')
old=s[s.index('    return _transfer(_call(transport, "POST", f"{BASE}/transfers/{transfer_id}/reversal"))'):]
old=old[:old.index("\n")+1]
rev='''    path = f"{BASE}/transfers/{transfer_id}/reversal"
    for n in range(1, MAX_ATTEMPTS + 1):
        r, failure = _attempt(transport, "POST", path, {}, None)
        if failure is None:
            return _transfer(json.loads(r.body))
        if n == MAX_ATTEMPTS:
            raise failure
        _wait(transport, n, r)
        if r is None or r.status in RETRY_STATUSES:
            # The reversal may have been applied: read the transfer before sending it again.
            current = get_transfer(transport, transfer_id)
            if current.status == "reversed":
                return current
    raise AssertionError("unreachable")
